@page "/track"
@page "/track/{TrackingNumber}"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<div class="container mt-4">
    <h1>Track Your Shipment</h1>

    <div class="row mt-3">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number (e.g., ST-20260709-A1B2C3D4)"
                       @bind="searchTrackingNumber" @bind:event="oninput"
                       @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isLoading">
                    @if (isLoading)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Search
                </button>
            </div>
        </div>
    </div>

    @if (searchPerformed)
    {
        @if (shipment is not null)
        {
            <div class="card mt-4">
                <div class="card-header">
                    <strong>Tracking Number:</strong> @shipment.TrackingNumber
                </div>
                <div class="card-body">
                    <div class="row">
                        <div class="col-md-6">
                            <p><strong>Origin:</strong> @shipment.Origin</p>
                            <p><strong>Destination:</strong> @shipment.Destination</p>
                            <p><strong>Description:</strong> @shipment.Description</p>
                        </div>
                        <div class="col-md-6">
                            <p><strong>Status:</strong> <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></p>
                            <p><strong>Shipped:</strong> @shipment.CreatedAt.ToString("MMM dd, yyyy")</p>
                            <p><strong>Estimated Delivery:</strong>
                                @if (shipment.EstimatedDelivery.HasValue)
                                {
                                    @shipment.EstimatedDelivery.Value.ToString("MMM dd, yyyy")
                                }
                                else
                                {
                                    <span class="text-muted">Not yet available</span>
                                }
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        }
        else
        {
            <div class="alert alert-warning mt-4">
                No shipment found with tracking number "<strong>@lastSearched</strong>". Please check the number and try again.
            </div>
        }
    }
</div>

@code {
    [Parameter]
    public string? TrackingNumber { get; set; }

    private string searchTrackingNumber = string.Empty;
    private Shipment? shipment;
    private bool isLoading;
    private bool searchPerformed;
    private string lastSearched = string.Empty;

    protected override async Task OnParametersSetAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            searchTrackingNumber = TrackingNumber;
            await SearchShipment();
        }
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(searchTrackingNumber))
            return;

        isLoading = true;
        lastSearched = searchTrackingNumber.Trim();
        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(lastSearched);
        }
        finally
        {
            isLoading = false;
            searchPerformed = true;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Shipments Dashboard</PageTitle>

<div class="container mt-4">
    <div class="d-flex justify-content-between align-items-center">
        <h1>Shipments Dashboard</h1>
        <button class="btn btn-success" @onclick="ShowCreateForm">+ New Shipment</button>
    </div>

    @if (showCreateForm)
    {
        <div class="card mt-3">
            <div class="card-header">Create New Shipment</div>
            <div class="card-body">
                <div class="row g-3">
                    <div class="col-md-4">
                        <label class="form-label">Origin</label>
                        <input type="text" class="form-control" @bind="newShipment.Origin" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Destination</label>
                        <input type="text" class="form-control" @bind="newShipment.Destination" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Customer Email</label>
                        <input type="email" class="form-control" @bind="newShipment.CustomerEmail" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Description</label>
                        <input type="text" class="form-control" @bind="newShipment.Description" />
                    </div>
                    <div class="col-md-3">
                        <label class="form-label">Estimated Delivery</label>
                        <input type="date" class="form-control" @bind="estimatedDeliveryDate" />
                    </div>
                    <div class="col-md-3 d-flex align-items-end gap-2">
                        <button class="btn btn-primary" @onclick="CreateShipment" disabled="@isSaving">
                            @if (isSaving)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                            }
                            Create
                        </button>
                        <button class="btn btn-outline-secondary" @onclick="CancelCreate">Cancel</button>
                    </div>
                </div>
            </div>
        </div>
    }

    @if (isLoading)
    {
        <div class="text-center mt-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (shipments.Count == 0)
    {
        <div class="alert alert-info mt-4">No shipments found. Create your first shipment above.</div>
    }
    else
    {
        <div class="row mt-3 mb-2">
            <div class="col-md-4">
                <input type="text" class="form-control" placeholder="Filter by destination..."
                       @bind="filterText" @bind:event="oninput" />
            </div>
            <div class="col-md-3">
                <select class="form-select" @bind="filterStatus">
                    <option value="">All Statuses</option>
                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                    {
                        <option value="@status">@status</option>
                    }
                </select>
            </div>
        </div>

        <table class="table table-striped table-hover mt-2">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Created</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.CreatedAt.ToString("MMM dd, yyyy")</td>
                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                        <td>
                            <select class="form-select form-select-sm" style="width:auto;display:inline-block"
                                    value="@s.Status" @onchange="e => UpdateStatus(s, e)">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }
</div>

@code {
    private List<Shipment> shipments = [];
    private bool isLoading = true;
    private bool showCreateForm;
    private bool isSaving;
    private Shipment newShipment = new();
    private DateTime? estimatedDeliveryDate;
    private string filterText = string.Empty;
    private string filterStatus = string.Empty;

    private IEnumerable<Shipment> FilteredShipments => shipments.Where(s =>
        (string.IsNullOrWhiteSpace(filterText) || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) &&
        (string.IsNullOrWhiteSpace(filterStatus) || s.Status.ToString() == filterStatus));

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ShowCreateForm() => showCreateForm = true;
    private void CancelCreate()
    {
        showCreateForm = false;
        newShipment = new();
        estimatedDeliveryDate = null;
    }

    private async Task CreateShipment()
    {
        isSaving = true;
        try
        {
            newShipment.EstimatedDelivery = estimatedDeliveryDate;
            await ShipmentService.CreateShipmentAsync(newShipment);
            showCreateForm = false;
            newShipment = new();
            estimatedDeliveryDate = null;
            await LoadShipments();
        }
        finally
        {
            isSaving = false;
        }
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

